// Guarded Autoset. Per the MHO900 programming guide, :AUToset is INVALID when
// the scope's AUTO function is disabled (:SYSTem:AUToscale = 0, a deliberate
// front-panel lockout) and also while waveform record/play is in progress.
// Deliberately does NOT force :SYSTem:AUToscale ON -- the lockout may be
// intentional; it tells you instead.
function qts(r){
    if(r===null||r===undefined)return"";
    if(typeof r==="string")return r;
    if(typeof r==="number")return String(r);
    if(r.data){var t=new TextDecoder().decode(new Uint8Array(r.data));return t.charAt(0)==='#'?t.substring(2+parseInt(t.charAt(1))):t;}
    return String(r);
}
await connection.acquire(true);
try {
    var en = qts(await connection.query(":SYSTem:AUToscale?")).trim();
    if (en === "0" || en.toUpperCase() === "OFF") {
        notify.warn("Autoset is disabled on the scope (:SYSTem:AUToscale = 0). "
            + "Enable it from the terminal with  :SYSTem:AUToscale ON  or via the "
            + "front panel, then press Auto again.");
    } else {
        connection.command(":AUToset");
        notify.info("Autoset triggered");
    }
} catch(e) {
    notify.error("Auto failed: " + e.message);
} finally {
    connection.release();
}

function qts(r){
    if(r===null||r===undefined)return"";
    if(typeof r==="string")return r;
    if(typeof r==="number")return String(r);
    if(r.data){var t=new TextDecoder().decode(new Uint8Array(r.data));return t.charAt(0)==='#'?t.substring(2+parseInt(t.charAt(1))):t;}
    return String(r);
}
function siFmt(v,unit){
    if(!isFinite(v))return String(v)+" "+unit;
    var a=Math.abs(v),sg=v<0?"-":"";
    var P=[[1e9,"G"],[1e6,"M"],[1e3,"k"],[1,""],[1e-3,"m"],[1e-6,"µ"],[1e-9,"n"],[1e-12,"p"]];
    if(a===0)return"0 "+unit;
    for(var i=0;i<P.length;i++){if(a>=P[i][0]*0.9999)return sg+parseFloat((a/P[i][0]).toPrecision(5))+" "+P[i][1]+unit;}
    return sg+a.toExponential(3)+" "+unit;
}
async function resetAndAcquire(){
    try{connection.release();}catch(e){}
    await new Promise(r=>setTimeout(r,400));
    await connection.acquire(true);
}

