    "MHO954": {bw:500e6, ch:4, sr:4e9,    mem:100e6, la:1, awgCh:2, awgBw:null,  awgIdx:1, awgOpt:1, hw:0},
    "MHO934": {bw:350e6, ch:4, sr:4e9,    mem:100e6, la:1, awgCh:2, awgBw:null,  awgIdx:1, awgOpt:1, hw:0},
    "DHO924S":{bw:250e6, ch:4, sr:1.25e9, mem:50e6,  la:1, awgCh:1, awgBw:25e6,  awgIdx:0, awgOpt:0, hw:1},
    "DHO924": {bw:250e6, ch:4, sr:1.25e9, mem:50e6,  la:1, awgCh:0, awgBw:null,  awgIdx:0, awgOpt:0, hw:0},
    "DHO914S":{bw:125e6, ch:4, sr:1.25e9, mem:50e6,  la:1, awgCh:1, awgBw:25e6,  awgIdx:0, awgOpt:0, hw:0},
    "DHO914": {bw:125e6, ch:4, sr:1.25e9, mem:50e6,  la:1, awgCh:0, awgBw:null,  awgIdx:0, awgOpt:0, hw:0},
    "DHO814": {bw:100e6, ch:4, sr:1.25e9, mem:25e6,  la:0, awgCh:0, awgBw:null,  awgIdx:0, awgOpt:0, hw:0},
    "DHO812": {bw:100e6, ch:2, sr:1.25e9, mem:25e6,  la:0, awgCh:0, awgBw:null,  awgIdx:0, awgOpt:0, hw:0},
    "DHO804": {bw:70e6,  ch:4, sr:1.25e9, mem:25e6,  la:0, awgCh:0, awgBw:null,  awgIdx:0, awgOpt:0, hw:0},
    "DHO802": {bw:70e6,  ch:2, sr:1.25e9, mem:25e6,  la:0, awgCh:0, awgBw:null,  awgIdx:0, awgOpt:0, hw:0}
};
async function detectModel(){
    var idn = qts(await connection.query("*IDN?")).trim();
    var model = (idn.split(",")[1]||"").trim();
    var row = MODELS[model];
    if(!row){
        // Unknown model: conservative defaults (smallest of the platform),
        // so nothing over-ranges. Announce it rather than guessing silently.
        notify.warn("Unknown model in *IDN? (\""+model+"\") -- using conservative defaults (25 Mpts). Known: "+Object.keys(MODELS).join(", "));
        row = {bw:70e6, ch:4, sr:1.25e9, mem:25e6, la:0, awgCh:0, awgBw:null, awgIdx:0, awgOpt:0, hw:0};
    }
    row.model = model || "unknown";
    return row;
}

// ── MHO98 Waveform Capture v2.2 ────────────────────────────────────────────────
// Captures all displayed analog channels to charts at full 12-bit fidelity.
// v2 changes vs v1:
//  - WAVeform:FORMat WORD (BYTE quantized the 12-bit ADC to 8 bits).
//  - In-script conversion to volts (Float32, chart format 1 FLOATS_32BIT):
//    EEZ Studio's own RIGOL_WORD chart format is broken upstream (reads bytes,
//    not 16-bit words) -- filed as eez-open/studio#1037; revisit when fixed.
//  - MODELS table + detectModel(): capture limits from the actual model row.
// Conversion: V = (raw - YORigin - YREFerence) * YINCrement  (preamble queried
// AFTER FORMat WORD is set, so its Y* values are WORD-scaled; any 12-in-16-bit
// alignment is absorbed by YINCrement/YREFerence from the preamble).
// UNVERIFIED (guide does not document WORD byte order): little-endian assembly
// below. If the first hardware test shows garbage, flip WORD_LITTLE_ENDIAN.
// To stop: click "Scripts" in the left nav (if not already there), then close
// any toast to reveal the Stop button underneath.
var WORD_LITTLE_ENDIAN = true;
var MAX_CAPTURE_PTS = 10000000;   // per channel; 10 Mpts = 20 MB transfer + 40 MB chart RAM
var CHUNK = 125000;               // points per DATA? chunk (250 KB in WORD format)

await resetAndAcquire();
var toast = notify.info("Capture: detecting model...", {autoClose:false});
try {
    var M = await detectModel();
    var NUM_CH = Math.min(M.ch, instrument.properties.channels.length);

    notify.update(toast,{render:M.model+": scanning channels...",autoClose:false});
    var shown = [];
    for (var c=1; c<=NUM_CH; c++) {
        var disp = qts(await connection.query("CHANnel"+c+":DISPlay?")).trim();
        if (disp==="1"||disp.toUpperCase()==="ON") shown.push(c);
    }
    if (shown.length===0) throw new Error("No channels are displayed");

    // Stop for stable RAW memory read
    connection.command(":STOP");
    connection.command(":WAVeform:MODE RAW");
    connection.command(":WAVeform:FORMat WORD");
    await new Promise(r=>setTimeout(r,200));

    var srate = parseFloat(qts(await connection.query(":ACQuire:SRATe?")));
    var tscale = parseFloat(qts(await connection.query(":TIMebase:SCALe?")));
    // Authoritative point count: :ACQuire:MDEPth? returns the actual memory
    // depth as a number (verified in the programming guide), even in AUTO mode.
    // The preamble's "points" field is NOT reliable for this: hardware testing
    // showed it reflects the current STARt/STOP read window, which persists
    // from the previous capture's last chunk -- that was the v2/v2.1 bug
    // (each run only re-read the previous run's final chunk window).
    var mdepth = parseFloat(qts(await connection.query(":ACQuire:MDEPth?")));
    if (!isFinite(mdepth) || mdepth < 1) throw new Error("Bad :ACQuire:MDEPth? reply");

    for (var k=0; k<shown.length; k++) {
        var ch = shown[k];
        connection.command(":WAVeform:SOURce CHANnel"+ch);
        // Reset the read window to the full memory BEFORE the preamble query,
        // so its X/Y parameters describe the full record, not a stale window.
        connection.command(":WAVeform:STARt 1");
        connection.command(":WAVeform:STOP "+mdepth);
        await new Promise(r=>setTimeout(r,100));

        var pre = qts(await connection.query(":WAVeform:PREamble?")).trim().split(",");
        var prePts = parseInt(pre[2]);
        var npts = mdepth;
        var xinc = parseFloat(pre[4]);
        var yinc = parseFloat(pre[7]), yor = parseFloat(pre[8]), yref = parseFloat(pre[9]);
        // RAW mode: XINCrement = 1/SampleRate per the programming guide -- use it
        // as the time axis for the returned data; fall back to ACQuire:SRATe?.
        var effRate = (isFinite(xinc) && xinc > 0) ? 1/xinc : srate;
        if (npts > MAX_CAPTURE_PTS) {
            throw new Error("Memory depth is "+siFmt(npts,"pts")+" -- above the "
                +siFmt(MAX_CAPTURE_PTS,"pts")+" capture limit. Lower it with "
                +":ACQuire:MDEPth (e.g. 10M) or raise MAX_CAPTURE_PTS in this script.");
        }
        var cScale = parseFloat(qts(await connection.query("CHANnel"+ch+":SCALe?")));
        var cUnit  = qts(await connection.query("CHANnel"+ch+":UNITs?")).trim();
        var unit = "volt";
        if (/CURR|AMP/i.test(cUnit)) unit="amp";
        else if (/WATT/i.test(cUnit)) unit="watt";

        var col  = instrument.properties.channels[ch-1].color;
        var colI = instrument.properties.channels[ch-1].colorInverse;

        // Chunked WORD read; convert each chunk to volts as Float32
        var data = [];
        var received = 0, shortChunks = 0;
        var nChunks = Math.ceil(npts / CHUNK);
        for (var j=0; j<nChunks; j++) {
            notify.update(toast,{render:M.model+" CH"+ch+": chunk "+(j+1)+"/"+nChunks+" ("+siFmt(npts,"pts")+", 12-bit)",autoClose:false});
            var start = j*CHUNK + 1;
            var stop  = Math.min((j+1)*CHUNK, npts);
            connection.command(":WAVeform:STARt "+start);
            connection.command(":WAVeform:STOP "+stop);
            var wf = await connection.query(":WAVeform:DATA?");
            if (wf && wf.data) {
                var b = new Uint8Array(wf.data);
                var n = Math.floor(b.length/2);
                var f = new Float32Array(n);
                if (WORD_LITTLE_ENDIAN) {
                    for (var i2=0;i2<n;i2++) f[i2] = ((b[2*i2] | (b[2*i2+1]<<8)) - yor - yref) * yinc;
                } else {
                    for (var i2=0;i2<n;i2++) f[i2] = (((b[2*i2]<<8) | b[2*i2+1]) - yor - yref) * yinc;
                }
                data.push(new Uint8Array(f.buffer));
                received += n;
                if (n < (stop - start + 1)) shortChunks++;
                if(wf.deleteLog) wf.deleteLog();
            }
        }

        var pct = npts > 0 ? Math.round(100*received/npts) : 0;
        var diag = "mdepth "+npts+" pts, preamble "+prePts+", received "+received+" ("+pct+"%)"
            + (shortChunks ? ", "+shortChunks+" short chunk(s)" : "")
            + "  xinc="+xinc+"  SRATe?="+siFmt(srate,"Sa/s");
        if (received < npts) notify.warn(M.model+" CH"+ch+": "+diag);
        session.addChart({
            description: M.model+" CH"+ch+"  "+siFmt(effRate,"Sa/s")+"  12-bit (WORD)  "+siFmt(cScale,"V")+"/div  ["+diag+"]",
            data: data, samplingRate: effRate,
            offset: 0, scale: 1, format: 1,
            unit: unit, color: col, colorInverse: colI,
            label: "CH"+ch,
            viewOptions:{axesLines:{type:"fixed",majorSubdivision:{horizontal:12,vertical:8},minorSubdivision:{horizontal:5,vertical:5}}},
            horizontalScale: tscale, verticalScale: cScale
        });
    }
    notify.dismiss(toast);
    notify.info(M.model+": captured "+shown.length+" channel(s) at 12-bit: CH"+shown.join(", CH"));
} catch(e) {
    notify.update(toast,{render:"Capture failed: "+e.message,autoClose:8000,type:"error"});
} finally {
    connection.command(":WAVeform:FORMat BYTE");
    connection.release();
}

