            connection.command(":SOURce"+n+":MOD:PM:INTernal:FREQuency "+vals.pmfreq);
            connection.command(":SOURce"+n+":MOD:PM:INTernal:FUNCtion "+vals.pmfunc);
        }
        connection.command(":SOURce"+n+":MOD:STATe ON");
    } else {
        connection.command(":SOURce"+n+":MOD:STATe OFF");
    }

    // ── 8. Align phase if requested ──────────────────────────────────────
    if (vals.alignphase) {
        connection.command(":SOURce"+n+":PHASe:SYNChronize");
    }

    // ── 9. Output state ──────────────────────────────────────────────────
    connection.command(":SOURce"+n+":OUTPut:STATe "+vals.output);

    // ── 10. Read back and confirm ─────────────────────────────────────────
    await new Promise(r=>setTimeout(r,300));
    var wv = qts(await connection.query(":SOURce"+n+":FUNCtion?")).trim();
    var fr = qts(await connection.query(":SOURce"+n+":FREQuency?")).trim();
    var am = qts(await connection.query(":SOURce"+n+":VOLTage:AMPLitude?")).trim();
    var of = qts(await connection.query(":SOURce"+n+":VOLTage:OFFSet?")).trim();
    var im = qts(await connection.query(":SOURce"+n+":IMPedance?")).trim();
    var ms = qts(await connection.query(":SOURce"+n+":MOD:STATe?")).trim();

    var summary = "AWG"+n+": "+wv;
    if (vals.wave!=="DC"&&vals.wave!=="NOISe") summary += "  "+siFmt(parseFloat(fr),"Hz");
    summary += "  Ampl "+siFmt(parseFloat(am),"Vpp")+"  Off "+siFmt(parseFloat(of),"V");
    summary += "  "+(im==="OMEG"||im==="0"?"HighZ":"Load");
    summary += "  OUT "+vals.output;
    if (ms==="1"||ms.toUpperCase()==="ON") summary += "  MOD:"+vals.modtype;

    notify.info(summary);

} catch(e) {
    notify.error("AWG setup failed: "+e.message);
} finally {
    connection.release();
}

function qts(r){
    if(r===null||r===undefined)return"";
    if(typeof r==="string")return r;
    if(typeof r==="number")return String(r);
    if(r.data){var t=new TextDecoder().decode(new Uint8Array(r.data));return t.charAt(0)==='#'?t.substring(2+parseInt(t.charAt(1))):t;}
    return String(r);
}
function siFmt(v,unit){
    if(!isFinite(v))return String(v)+" "+unit;
    var a=Math.abs(v),sg=v<0?"-":"";
    var P=[[1e9,"G"],[1e6,"M"],[1e3,"k"],[1,""],[1e-3,"m"],[1e-6,"\u00b5"],[1e-9,"n"],[1e-12,"p"]];
    if(a===0)return"0 "+unit;
    for(var i=0;i<P.length;i++){if(a>=P[i][0]*0.9999)return sg+parseFloat((a/P[i][0]).toPrecision(5))+" "+P[i][1]+unit;}
    return sg+a.toExponential(3)+" "+unit;
}
async function resetAndAcquire(){
    try{connection.release();}catch(e){}
    await new Promise(r=>setTimeout(r,400));
    await connection.acquire(true);
}

